(function(){
let selected=0,signature='',reportHTML='';const money=n=>fmt(n)+' 萬',cap=n=>n===null?'無借款':pct(n*100);
function plan(m){return m.planning?.cashflow??RiskCashflow.normalize();}
function storePlan(m){if(!m.planning)m.planning=RiskPlanning.normalize();if(!m.planning.cashflow)m.planning.cashflow=plan(m);return m.planning.cashflow;}
function metric(n,v){return `<div><span>${n}</span><strong>${v}</strong></div>`;}
function monthlyTable(r){return `<div class="tablewrap"><table><thead><tr><th>月份</th><th>收入</th><th>生活／單次支出</th><th>質押利息</th><th>融資利息</th><th>展延補本金</th><th>月底現金</th><th>低於預留額</th></tr></thead><tbody>${r.rows.map(row=>`<tr class="${row.shortfall>0?'cashLow':''}"><td>${row.month}${row.items.length?'<small>'+row.items.map(esc).join('、')+'</small>':''}</td>${['income','living','pledgeInterest','marginInterest','principal','balance','shortfall'].map(k=>`<td>${fmt(row[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function render(rebuild=false){const key=JSON.stringify(family.map(m=>[m.name,m.data.pools.map(p=>[p.name,p.pledgeDebt,p.marginDebt])]));selected=Math.min(selected,family.length-1);const m=family[selected],p=plan(m);if(rebuild||signature!==key){signature=key;$('cashflowInputs').innerHTML=`<div class="fields"><label>成員<select id="yearMember">${family.map((m,i)=>`<option value="${i}" ${selected===i?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><label>起始月份<input id="yearStart" type="month" value="${p.startMonth}"></label></div><p class="hint">金額：萬元 · 同人現金共用，家人之間不互抵。</p><div class="fields">${[['monthlyIncome','每月固定收入'],['monthlyExpense','每月固定支出'],['reserve','希望保留的現金']].map(([k,n])=>`<label>${n}<input data-year-field="${k}" type="number" min="0" step="0.01" value="${p[k]}"></label>`).join('')}</div><label class="yearCheck"><input id="yearPrincipal" type="checkbox" ${p.includePrincipal?'checked':''}>展延時計入補本金至166%</label><h3>借款利率與展延月份</h3><div class="tablewrap"><table><thead><tr><th>券商</th><th>質押年利率%</th><th>下次質押展延月</th><th>融資年利率%</th></tr></thead><tbody>${m.data.pools.map((a,i)=>`<tr><td>${esc(a.name)}</td><td>${a.pledgeDebt>0?`<input aria-label="${esc(a.name)} 質押年利率" data-year-pool="${i}" data-year-key="pledgeRate" min="0" max="100" step="0.01" type="number" value="${a.pledgeRate??''}" placeholder="待填">`:'—'}</td><td>${a.pledgeDebt>0?`<input aria-label="${esc(a.name)} 下次質押展延月" data-year-pool="${i}" data-year-key="renewalMonth" type="month" value="${a.renewalMonth??''}">`:'—'}</td><td>${a.marginDebt>0?`<input aria-label="${esc(a.name)} 融資年利率" data-year-pool="${i}" data-year-key="marginRate" min="0" max="100" step="0.01" type="number" value="${a.marginRate??''}" placeholder="待填">`:'—'}</td></tr>`).join('')}</tbody></table></div><div class="sectionhead"><h3>單次收入／支出</h3><button id="addYearEvent">＋收支</button></div><div id="yearEvents">${p.events.map((e,i)=>`<div class="yearEvent"><label>名稱<input data-year-event="${i}" data-event-key="name" value="${esc(e.name)}" maxlength="80"></label><label>月份<input type="month" data-year-event="${i}" data-event-key="month" value="${e.month}"></label><label>類型<select data-year-event="${i}" data-event-key="kind"><option value="expense" ${e.kind==='expense'?'selected':''}>支出</option><option value="income" ${e.kind==='income'?'selected':''}>收入</option></select></label><label>金額<input type="number" min="0" step="0.01" data-year-event="${i}" data-event-key="amount" value="${e.amount}"></label><button data-remove-year-event="${i}">移除</button></div>`).join('')}</div>`;}
try{const r=RiskCashflow.calculate(m.data,p);$('cashflowResults').innerHTML=`<h3>${esc(m.name)} · ${r.rows[0].month} 至 ${r.rows[11].month}</h3>${r.missing.length?'<p class="notice warning">資料未齊：'+r.missing.map(esc).join('、')+'。以下為已知收支估算。</p>':''}<div class="summary">${metric('目前現金',money(m.data.cash))}${metric('全年利息',money(r.interest))}${metric('全年補本金',money(r.principal))}${metric('一年後現金',money(r.endBalance))}${metric('最低預計現金',money(r.minBalance))}${metric('達到預留額需再準備',money(r.needed))}</div><p class="notice ${r.needed>0?'danger':''}">${r.firstShortfall?'首次低於預留額：'+r.firstShortfall:r.needed>0?'目前現金已低於預留額':r.missing.length?'尚有未計費用，暫不判定現金足夠':'已填收支下，未來12個月可維持預留現金'}</p>${monthlyTable(r)}<p class="hint">假設市值與利率不變；補本金後，後續質押利息按剩餘本金計算。未計股災補款、手續費或未輸入的收支。固定收支從起始月完整列入。</p>`;}catch(e){$('cashflowResults').textContent=e.message;}}
const reportCSS=`body{font-family:system-ui,-apple-system,'Noto Sans TC',sans-serif;color:#18354b;margin:0;background:white}.clientReport{max-width:1050px;margin:auto;padding:32px}h1{font-size:26px}h2{font-size:20px;border-bottom:2px solid #147c74;padding-bottom:10px;margin-top:28px}h3{font-size:16px;margin-top:24px}p{line-height:1.7}table{border-collapse:collapse;width:100%;font-size:11px;text-align:right}th,td{padding:9px 7px;border-bottom:1px solid #d8e4e8}th:first-child,td:first-child{text-align:left}th{background:#edf5f7}small{display:block;font-size:10px;color:#627686}.reportStats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.reportStats>div{padding:14px;background:#edf5f7}.reportStats strong{display:block;font-size:20px}.reportNote{font-size:12px;color:#627686}.reportMember{break-before:page}.cashLow{background:#fff1ef}.reportBadge{padding:10px;background:#edf5f7}.reportPrint{margin:20px}@media(max-width:700px){.reportStats{grid-template-columns:repeat(2,1fr)}.clientReport{padding:16px}.tablewrap{overflow:auto}}@media print{@page{size:A4 landscape;margin:12mm}.clientReport{padding:0;max-width:none}.reportPrint{display:none}table{white-space:normal}tr,.reportStats{break-inside:avoid}.tablewrap{overflow:visible}}`;
function createReport(){RiskData.normalize({version:2,members:family});const drop=Number($('drop').value)/100;family.forEach(m=>{RiskEngine.validate(m.data);RiskPlanning.normalize(m.planning??{});});const data=family.map(m=>({m,present:RiskEngine.calculate(m.data),c:RiskEngine.capacity(m.data),v:RiskEngine.readiness(m.data,drop),year:RiskCashflow.calculate(m.data,plan(m)),tax:RiskPlanning.estate(m.data,RiskPlanning.normalize(m.planning??{}).estate)}));const sum=k=>data.reduce((n,d)=>n+(k==='cash'?d.m.data.cash:d.present[k]),0);
return `<article class="clientReport"><h1>家族資產與現金需求報告</h1><p>資產基準日：${esc($('date').value)} · ${family.length} 位成員 · 金額單位：萬元 · 股票下跌情境：${pct(drop*100)}</p><div class="reportStats">${metric('家族股票市值',money(sum('stock')))}${metric('家族借款',money(sum('debt')))}${metric('家族淨資產',money(sum('equity')))}${metric('家族現金',money(sum('cash')))}</div><h2>資產與風險總覽</h2><div class="tablewrap"><table><thead><tr><th>成員</th><th>淨資產</th><th>借款</th><th>現金</th><th>曝險倍數</th><th>原部位可跌</th><th>先用現金可跌</th><th>最後加現股可跌</th></tr></thead><tbody>${data.map(d=>`<tr><td>${esc(d.m.name)}</td><td>${fmt(d.present.equity)}</td><td>${fmt(d.present.debt)}</td><td>${fmt(d.m.data.cash)}</td><td>${d.present.leverage===null?'—':fmt(d.present.leverage)+'倍'}</td><td>${cap(d.c.current)}</td><td>${cap(d.c.cashOnly)}</td><td>${cap(d.c.cash)}</td></tr>`).join('')}</tbody></table></div><p class="reportNote">質押166%／融資130%保守門檻；股票同步下跌。同人現金共用，現股僅補所屬券商，家人之間不互抵。家族合計展示資產，沒有合併計算可扛跌幅。</p><h2>一年現金與遺產稅總覽</h2><div class="tablewrap"><table><thead><tr><th>成員</th><th>規劃期間</th><th>全年利息</th><th>展延補本金</th><th>期末現金</th><th>需另備現金</th><th>估計遺產稅</th><th>資料狀態</th></tr></thead><tbody>${data.map(d=>`<tr><td>${esc(d.m.name)}</td><td>${d.year.rows[0].month}～${d.year.rows[11].month}</td><td>${fmt(d.year.interest)}</td><td>${fmt(d.year.principal)}</td><td>${fmt(d.year.endBalance)}</td><td>${fmt(d.year.needed)}</td><td>${fmt(d.tax.tax)}</td><td>${d.year.missing.length?'待補'+d.year.missing.length+'項':'利率／月份已填'}</td></tr>`).join('')}</tbody></table></div><p class="reportNote">遺產稅按個人及已填扣除資料估算，採2026年規則，未列入每年現金支出。現金規劃假設市值與利率不變，未計股災補款。資料未齊時顯示已知收支。</p>${data.map(d=>`<section class="reportMember"><h2>${esc(d.m.name)} · 個人資產與風險</h2><p class="reportBadge">曝險 ${d.present.leverage===null?'—':fmt(d.present.leverage)+'倍'}；原部位可跌 ${cap(d.c.current)}，先用現金可跌 ${cap(d.c.cashOnly)}，最後加現股最多可跌 ${cap(d.c.cash)}。</p><p>股票下跌 ${pct(drop*100)}：${esc(d.v.label)}。原部位需還 ${money(d.v.original.repay)}，先用現金 ${money(d.v.cashUsed)}；最後加現股後仍缺 ${money(d.v.support.cashGap)}。</p>${d.m.data.pools.some(p=>p.legacyCombined)?'<p class="reportNote">含未核對舊合計資料，請先確認質押／融資拆分。</p>':''}<h3>券商資產（萬元）</h3><table><thead><tr><th>券商</th><th>現金</th><th>未設質現股</th><th>質押市值／借款</th><th>融資市值／借款</th></tr></thead><tbody>${d.m.data.pools.map(p=>`<tr><td>${esc(p.name)}</td><td>${fmt(p.cash)}</td><td>${fmt(p.other)}</td><td>${fmt(p.pledgeValue)}／${fmt(p.pledgeDebt)}</td><td>${fmt(p.marginValue)}／${fmt(p.marginDebt)}</td></tr>`).join('')}</tbody></table><h3>未來12個月現金需求</h3><p>每月收入 ${money(d.year.plan.monthlyIncome)}；支出 ${money(d.year.plan.monthlyExpense)}；現金預留 ${money(d.year.plan.reserve)}。${d.year.missing.length?'待補：'+d.year.missing.map(esc).join('、'):'利率與展延月份已填。'}</p>${monthlyTable(d.year)}<h3>個人遺產稅估算</h3><p>遺產總額 ${money(d.tax.gross)} − 免稅額 1,333萬 − 扣除 ${money(d.tax.deductions)} ＝ 課稅淨額 ${money(d.tax.taxable)}；估計稅額 <strong>${money(d.tax.tax)}</strong>。</p><p class="reportNote">正式申報以繼承日課稅價值及可證明債務為準。<a href="https://www.ntbna.gov.tw/singlehtml/374fe8c4b18e48c691a6806ac02b9984?cntId=8236871cbd7e4b5686bd700f59fb1429">115年度免稅及扣除額</a> · <a href="https://www.etax.nat.gov.tw/etwmain/tax-info/understanding/tax-q-and-a/national/estate-tax/payable/aYEGrlw">財政部稅率</a>。</p></section>`).join('')}<p class="reportNote">報告為輸入資料快照，未包含另存的曝險模擬交易。補本金後，後續利息按剩餘本金估算。實際計息、追繳及展延依契約。</p></article>`;}
function openReport(){try{reportHTML=createReport();$('clientReportContent').innerHTML=reportHTML;$('clientReportDialog').showModal();}catch(e){$('error').textContent='無法產生報告：'+e.message;}}
document.addEventListener('input',e=>{const t=e.target,m=family[selected];if(t.dataset.yearField){storePlan(m)[t.dataset.yearField]=Number(t.value);mark();render();}if(t.dataset.yearPool!==undefined){const p=m.data.pools[+t.dataset.yearPool],k=t.dataset.yearKey;if(t.value==='')delete p[k];else p[k]=k==='renewalMonth'?t.value:Number(t.value);mark();RiskExtras.render();render();}if(t.dataset.yearEvent!==undefined){storePlan(m).events[+t.dataset.yearEvent][t.dataset.eventKey]=t.dataset.eventKey==='amount'?Number(t.value):t.value;mark();render();}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='yearMember'){selected=Number(t.value);render(true);}if(t.id==='yearStart'){storePlan(family[selected]).startMonth=t.value;mark();render();}if(t.id==='yearPrincipal'){storePlan(family[selected]).includePrincipal=t.checked;mark();render();}});
document.addEventListener('click',e=>{const t=e.target;if(t.id==='addYearEvent'){const p=storePlan(family[selected]);if(p.events.length>=100)return;p.events.push({name:'單次支出',month:p.startMonth,kind:'expense',amount:0});mark();render(true);}if(t.dataset.removeYearEvent!==undefined){storePlan(family[selected]).events.splice(+t.dataset.removeYearEvent,1);mark();render(true);}});
$('cashflowTab').onclick=()=>showPage('cashflow');$('dashboardReport').onclick=openReport;$('cashReport').onclick=openReport;$('closeClientReport').onclick=()=>$('clientReportDialog').close();$('printClientReport').onclick=()=>{document.body.classList.add('printingClient');window.print();};window.addEventListener('afterprint',()=>document.body.classList.remove('printingClient'));
$('downloadClientReport').onclick=()=>{const html='<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>家族資產報告</title><style>'+reportCSS+'</style></head><body><button class="reportPrint" onclick="window.print()">列印／存成 PDF</button>'+reportHTML+'</body></html>',url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='family-report-'+($('date').value||'snapshot')+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
window.RiskYear={render};render(true);
})();
